import { FULL_CASE_FOLDING } from "./case-folding-data.js";
/**
 * Applies Unicode 15.1 default full case folding (statuses C and F).
 * The mapping data is embedded so results do not depend on runtime locale.
 */
export function foldCase(input) {
    let result = "";
    for (const char of input) {
        const codePoint = char.codePointAt(0) ?? 0;
        const mapping = FULL_CASE_FOLDING.get(codePoint);
        result += mapping
            ? String.fromCodePoint(...mapping)
            : char;
    }
    return result;
}
